export interface IResetPasswordModel {

    id: string;
    email: string;
    password: string;
    token: string;
}

export class ResetPasswordModel implements IResetPasswordModel {

    id: string;
    email: string;
    password: string;
    token: string;

    constructor(
        id: string,
        email: string,
        password: string,
        token: string
    ) {
        this.id = id;
        this.email = email;
        this.password = password;
        this.token = token;
    }
}

export interface IConfirmEmailModel {

    id: string;
    email: string;
}

export class ConfirmEmailModel implements IConfirmEmailModel {

    id: string;
    email: string;

    constructor(
        id: string,
        email: string
    ) {
        this.id = id;
        this.email = email;
    }
}


